import html2canvas from 'html2canvas';
import jsPDF from 'jspdf';
import * as XLSX from 'xlsx';
import { useScheduleStore } from '../store/scheduleStore';

/**
 * 截图模式：导出前隐藏编辑按钮和占位提示，导出后恢复
 */
const withScreenshotMode = async <T>(fn: () => Promise<T>): Promise<T> => {
  const originalHidePlaceholders = useScheduleStore.getState().hidePlaceholders;

  // 开启截图模式：隐藏编辑按钮和占位提示
  useScheduleStore.setState({ hidePlaceholders: true });

  // 等待 DOM 重新渲染
  await new Promise((resolve) => setTimeout(resolve, 100));

  try {
    return await fn();
  } finally {
    // 恢复原状态
    useScheduleStore.setState({ hidePlaceholders: originalHidePlaceholders });
  }
};

/**
 * html2canvas 垂直居中修正（仅作用于克隆 DOM — 不影响页面实际展示）
 *
 * 用户反馈之前的 flex→block + paddingTop 精确计算方案反而让文字更偏下。
 * 原因：克隆节点尚未进入渲染树，getBoundingClientRect() 返回 0，
 *       style.height 是 "80px" 形式的字符串，但换算逻辑 + 丢弃 flex 居中反而使
 *       原本依赖 CSS 类名（"flex items-center h-full"）在 html2canvas 内部
 *       自带的一套文字测量值作废，结果更差。
 *
 * 新策略：**最小侵入** — 保留原有布局（flex + h-full 依然保留给 html2canvas 渲染），
 * 只做两件事：
 *   1) 强制 `<td>` 和 `<th>` verticalAlign:'top' + paddingTop 精确上移量（约 td 高的 6%）；
 *   2) 对内层 div 与所有子孙元素，统一加 **负 marginTop = -6px**（硬偏移，不依赖测量），
 *      并额外 `transform: translateY(-4px)`，彻底抵消 html2canvas 基线下偏。
 *   3) 恢复 line-height 为 normal，避免 line-height:1 让内容框高度更差。
 *
 * 这样即使 html2canvas 对 flex 居中略有偏差，8~10px 的上移余量也足以覆盖。
 */
// 课程/休息 td（有内层 flex div）的上移量
const COURSE_FIX_OFFSET_PX = 19;
// 时间列 td（直接包含文字、无内层 div）的单独上移量
const TIME_FIX_OFFSET_PX = -19;
// 表头 th 上移量（教室、时间标题）
const TH_FIX_OFFSET_PX = 19;

const applyVerticalCenteringFix = (clonedDoc: Document) => {
  // ========== 1. 所有 td：课程内容、课间休息、时间列 ==========
  const tds = clonedDoc.querySelectorAll('td');
  tds.forEach((td) => {
    const tdEl = td as HTMLTableCellElement;
    tdEl.style.verticalAlign = 'middle';

    const innerDiv = tdEl.firstElementChild as HTMLDivElement | null;

    // -------- 1A. 有内层 div（课程单元格 / 休息单元格，CourseCell 渲染的） --------
    if (innerDiv && innerDiv.tagName === 'DIV') {
      innerDiv.style.marginTop = `-${COURSE_FIX_OFFSET_PX}px`;
      innerDiv.style.transform = 'translateY(0px)';

      const subChildren = innerDiv.querySelectorAll('div');
      subChildren.forEach((el) => {
        const child = el as HTMLElement;
        child.style.marginTop = '0px';
        child.style.paddingTop = '0px';
        child.style.paddingBottom = '0px';
      });
      return;
    }

    // -------- 1B. 直接是文字的 td：时间列（ScheduleTable 渲染的 08:00-09:50） --------
    // html2canvas 对纯文字 td + verticalAlign:middle 基线也会偏下，
    // 且这些 td 本来还带有 px-4 / py-0.5 等类（Tailwind 的 padding），
    // 这里显式把 paddingTop 清零并设置精确 paddingTop = (tdHeight - fontSize)/2 - bias。
    // 但因为无法精确测（克隆节点未渲染），改用 transform 向上平移 + 配合 line-height:1 来压缩。
    tdEl.style.paddingTop = '0px';
    tdEl.style.paddingBottom = '0px';
    tdEl.style.lineHeight = '1';
    // 时间文字盒子：用 paddingTop 把内容顶到居中偏上
    tdEl.style.paddingTop = `${TIME_FIX_OFFSET_PX}px`;
    // 再整体用 transform 额外向上提 4px（基线修正）
    tdEl.style.transform = 'translateY(-4px)';
  });

  // ========== 2. 表头 th：时间 / 教室1 / 教室2 ... ==========
  const ths = clonedDoc.querySelectorAll('th');
  ths.forEach((th) => {
    const thEl = th as HTMLTableCellElement;
    thEl.style.verticalAlign = 'middle';

    const innerDiv = thEl.firstElementChild as HTMLDivElement | null;
    if (innerDiv && innerDiv.tagName === 'DIV') {
      innerDiv.style.marginTop = `-${TH_FIX_OFFSET_PX}px`;
    } else {
      // th 内直接是文字（卡片模式下的"时间"/"教室1"）
      thEl.style.paddingTop = '0px';
      thEl.style.lineHeight = '1';
      thEl.style.transform = `translateY(-${Math.round(TH_FIX_OFFSET_PX * 0.5)}px)`;
    }
  });

  // ========== 3. 日期标题："周六排课" 所在 h2 ==========
  const dayTitles = clonedDoc.querySelectorAll('h2');
  dayTitles.forEach((h) => {
    (h as HTMLElement).style.marginTop = '0';
    (h as HTMLElement).style.marginBottom = '0';
    (h as HTMLElement).style.transform = 'translateY(0)';
  });
};

/**
 * 导出 PNG 图片
 * 使用 html2canvas 将 DOM 元素截图为高清 PNG
 */
export const exportAsImage = async (elementId: string, fileName: string = 'schedule.png') => {
  const element = document.getElementById(elementId);
  if (!element) {
    alert('找不到要导出的元素');
    return;
  }

  await withScreenshotMode(async () => {
    try {
      const canvas = await html2canvas(element, {
        scale: 2,
        backgroundColor: '#ffffff',
        useCORS: true,
        logging: false,
        onclone: (clonedDoc) => {
          applyVerticalCenteringFix(clonedDoc);
        },
      });

      const link = document.createElement('a');
      link.download = fileName;
      link.href = canvas.toDataURL('image/png');
      link.click();
    } catch (error) {
      console.error('导出图片失败:', error);
      alert('导出图片失败，请重试');
    }
  });
};

/**
 * 导出 PDF 文件
 * 使用 html2canvas 截图后，通过 jsPDF 生成 A4 分页 PDF
 */
export const exportAsPDF = async (elementId: string, fileName: string = 'schedule.pdf') => {
  const element = document.getElementById(elementId);
  if (!element) {
    alert('找不到要导出的元素');
    return;
  }

  await withScreenshotMode(async () => {
    try {
      const canvas = await html2canvas(element, {
        scale: 2,
        backgroundColor: '#ffffff',
        useCORS: true,
        logging: false,
        onclone: (clonedDoc) => {
          applyVerticalCenteringFix(clonedDoc);
        },
      });

      // A4 纸参数（210mm × 297mm）
      const pageWidth = 210;
      const pageHeight = 297;
      const imgWidth = pageWidth;
      const imgHeight = (canvas.height * imgWidth) / canvas.width;

      const pdf = new jsPDF('p', 'mm', 'a4');
      let heightLeft = imgHeight;
      let position = 0;

      const imgData = canvas.toDataURL('image/png');
      pdf.addImage(imgData, 'PNG', 0, position, imgWidth, imgHeight);
      heightLeft -= pageHeight;

      // 循环添加续页
      while (heightLeft > 0) {
        position = heightLeft - imgHeight;
        pdf.addPage();
        pdf.addImage(imgData, 'PNG', 0, position, imgWidth, imgHeight);
        heightLeft -= pageHeight;
      }

      pdf.save(fileName);
    } catch (error) {
      console.error('导出PDF失败:', error);
      alert('导出PDF失败，请重试');
    }
  });
};

export const exportAsExcel = () => {
  const store = useScheduleStore.getState();
  const { timeSlots, classrooms, courses, title, date } = store;

  const workbook = XLSX.utils.book_new();

  const days = ['周五', '周六', '周日'] as const;

  days.forEach((day) => {
    const sheetData: string[][] = [];

    sheetData.push([`${day}排课 - ${title}`]);
    sheetData.push([`导出日期: ${date}`]);
    sheetData.push([]);

    const headerRow = ['时间', ...classrooms.map((c) => c.name)];
    sheetData.push(headerRow);

    timeSlots.forEach((slot) => {
      const row: string[] = [`${slot.startTime} - ${slot.endTime}`];
      
      classrooms.forEach((classroom) => {
        const course = courses.find(
          (c) =>
            c.dayType === day &&
            c.timeSlotId === slot.id &&
            c.classroomId === classroom.id
        );

        if (course) {
          if (course.entryType === 'course' && course.grade && course.subject) {
            row.push(`${course.grade}${course.subject}`);
          } else if (course.entryType === 'custom' && course.customText) {
            row.push(course.customText);
          } else {
            row.push('');
          }
        } else {
          row.push('');
        }
      });

      sheetData.push(row);
    });

    const worksheet = XLSX.utils.aoa_to_sheet(sheetData);
    
    worksheet['!cols'] = classrooms.map(() => ({ wch: 15 }));
    worksheet['!cols'] = [{ wch: 20 }, ...classrooms.map(() => ({ wch: 15 }))];

    XLSX.utils.book_append_sheet(workbook, worksheet, `${day}排课`);
  });

  const fileName = `${title}_${date}.xlsx`;
  XLSX.writeFile(workbook, fileName);
};

export const exportSettingsToFile = () => {
  const store = useScheduleStore.getState();
  const jsonString = store.exportSettings();
  
  const blob = new Blob([jsonString], { type: 'application/json' });
  const link = document.createElement('a');
  const url = URL.createObjectURL(blob);
  
  link.href = url;
  link.download = `schedule_settings_${new Date().toISOString().split('T')[0]}.json`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
};

export const importSettingsFromFile = (file: File) => {
  return new Promise<void>((resolve, reject) => {
    const reader = new FileReader();
    
    reader.onload = (e) => {
      try {
        const jsonString = e.target?.result as string;
        const store = useScheduleStore.getState();
        store.importSettings(jsonString);
        resolve();
      } catch (error) {
        reject(error);
      }
    };
    
    reader.onerror = (e) => {
      reject(e);
    };
    
    reader.readAsText(file);
  });
};
